# Meeting 1, file c: part 5 (entities, a table, a first query), part 6 (working with an AI assistant).

# ------------------------------------------------------------------ part 5
opener(5, 'מדרישה לנתונים', 'אם אלה הדרישות, מה המערכת צריכה לזכור כדי לקיים אותן?',
       ['מוצאים בתוך הדרישות את הדברים שהמערכת צריכה לזכור', 'מבחינים בין ישות, מאפיין ומזהה', 'רואים איך ישות הופכת לטבלה', 'קוראים שאילתה ראשונה, קליק אחר קליק, בלי להקליד'], 40)

SS('e-nouns', 'קוראים את הדרישות, ומסמנים שמות עצם',
   P('אלה שלוש דרישות שנועה ניסחה. כל שם עצם שחוזר הוא מועמד למשהו שהמערכת צריכה לזכור.') +
   CARD('<p>' + TX('1. כאשר **המלצר** מאשר **הזמנה** בטאבלט, המערכת תציג אותה על מסך המטבח בתוך 5 שניות.') + '</p>', 1) +
   CARD('<p>' + TX('2. כאשר הטבח מסמן ש**מנה** אזלה, המערכת תסמן אותה כלא זמינה אצל כל **מלצר** בתוך 10 שניות.') + '</p>', 2) +
   CARD('<p>' + TX('3. כאשר המלצר סוגר **שולחן**, המערכת תחשב את החשבון לפי ה**מנות** שב**הזמנות** של השולחן.') + '</p>', 3) +
   BAND('dg', 'ארבעה שמות עצם חוזרים: **הזמנה, מנה, מלצר, שולחן**. אלה הדברים שהמערכת חייבת לזכור.', 4))

SS('e-def', 'ישות ומאפיין',
   ROW(DEF('ישות (Entity)', 'דבר שהמערכת צריכה לזכור עליו פרטים: אדם, חפץ או אירוע. יש ממנו הרבה, וכל אחד נבדל מהאחרים.', 'הזמנה. בביסטרו יש 1,200 כאלה בחודש.', 1),
       DEF('מאפיין (Attribute)', 'פרט אחד שזוכרים על ישות. לכל ישות כמה מאפיינים, ולכל מאפיין ערך אחד.', 'להזמנה: באיזו משמרת, מי המלצר, האם חזרה למטבח.', 2)) +
   TABLE(['הישות', 'מאפיינים שהדרישות מחייבות'], [['הזמנה', 'מתי נפתחה, באיזה שולחן, מי המלצר, האם חזרה למטבח'], ['מנה', 'שם, מחיר, האם זמינה כרגע'], ['מלצר', 'שם, משמרת'], ['שולחן', 'מספר, קומה']], n0=3) +
   BAND('tip', 'שימו לב לקשר לחלק 3: ״האם חזרה למטבח״ ו״מי המלצר״ הם בדיוק הנתונים שחסרו לאולאף כדי להחליט.', 7))

SORTER('e-sort', 'ישות, מאפיין או פעולה?', 'פעילות: ישות, מאפיין או פעולה?',
       'לכל מילה מתוך הדרישות קבעו מה היא במודל הנתונים.', ['ישות', 'מאפיין', 'פעולה'],
       [('מחיר המנה', 1, 'פרט אחד על מנה. למנה אחת יש מחיר אחד.'),
        ('לקוח קבוע', 0, 'יש רבים כאלה, וזוכרים על כל אחד פרטים: שם, טלפון, מה הוא אוהב.'),
        ('לאשר הזמנה', 2, 'פועל. זו פעולה שהמערכת מאפשרת, לא דבר שזוכרים.'),
        ('שעת פתיחת ההזמנה', 1, 'פרט אחד על הזמנה.'),
        ('משמרת', 0, 'יש כמה משמרות, ולכל אחת יום, שעות וצוות. זו ישות.'),
        ('להפיק חשבון', 2, 'פעולה. החשבון עצמו יכול להיות ישות, ההפקה היא פעולה.')],
       story='אתי מוסיפה לרשימה מילים שעלו בפגישה עם הצוות של ביסטרו אולאף. נועה ממיינת אותן לפני שהיא מעבירה את הרשימה לד״ר קונדילה.')

SS('e-id', 'שני יוסי במשמרת אחת: למה צריך מזהה',
   ROW(CARD('<b class="ct">הבעיה</b>' + UL(['בביסטרו עובדים שני מלצרים בשם יוסי.', 'בדוח כתוב: ״יוסי: 9 הזמנות חזרו״.', 'איזה יוסי? מי מהם יקבל הדרכה?'], 1), cls='badc'),
       CARD('<b class="ct">הפתרון</b>' + TABLE(['מספר עובד', 'שם', 'משמרת'], [['17', 'יוסי', 'ערב'], ['23', 'יוסי', 'צהריים']], n0=4) + '<p class="st" data-n="60">' + TX('עכשיו הדוח אומר: ״עובד 17: 9 הזמנות חזרו״.') + '</p>', cls='good')) +
   DEF('מזהה (Identifier)', 'מספר או קוד ייחודי שמבדיל בין שני פריטים, גם אם כל שאר הפרטים שלהם זהים.', 'מספר עובד 17, הזמנה מספר 1201.', 7) +
   BAND('trap', 'שם אינו מזהה. שמות חוזרים על עצמם, משתנים, ונכתבים בכמה צורות.', 8))

PICK('e-pick', 'מה יכול לשמש מזהה?', 'פעילות: מה מתאים לשמש מזהה?',
     'סמנו את הפרטים שאפשר לסמוך עליהם כמזהה: ייחודיים, ואינם משתנים.',
     [('מספר הזמנה רץ שהמערכת נותנת: 1201, 1202, 1203', 1, 'ייחודי ואינו משתנה. זה מזהה קלאסי.'),
      ('שם המנה: ״פסטה היום״', 0, 'שמות מנות משתנים, ולפעמים שתי מנות נקראות כמעט אותו דבר.'),
      ('מספר השולחן, כשכל שולחן ממוספר פעם אחת ואינו מתחלף', 1, 'כל עוד המספור קבוע וייחודי, הוא מזהה טוב.'),
      ('השעה שבה נפתחה ההזמנה', 0, 'שתי הזמנות יכולות להיפתח באותה דקה.'),
      ('מספר עובד שניתן לכל מלצר ביום הקליטה', 1, 'ייחודי לכל עובד, ואינו משתנה גם אם השם משתנה.'),
      ('שם פרטי של המלצר', 0, 'ראינו: שני יוסי במשמרת אחת.')],
     story='נועה צריכה לבחור מזהה לכל ישות במערכת של ביסטרו אולאף. לפניכם שישה פרטים שהוצעו בפגישה.', cols=2)

SS('e-table', 'מישות לטבלה',
   P('כשהמערכת זוכרת ישות, היא שומרת אותה בטבלה. את בניית הטבלאות נלמד במפגש 2. כאן רק רואים את הרעיון.') +
   ROW('<div class="mock"><div class="mb"><span>הטבלה <bdi dir="ltr">orders</bdi></span><small>הדמיה</small></div><div class="mi">' +
       TABLE(['order_id', 'shift', 'waiter', 'returned'], [['1201', 'thu_eve', 'יוסי', 'yes'], ['1202', 'thu_eve', 'דנה', 'no'], ['1203', 'fri_noon', 'יוסי', 'yes']], n0=2) + '</div></div>',
       '<div>' + CT('טבלה = ישות', 'טבלה אחת לכל ישות. כאן: הזמנות.', 1) + CT('שורה = פריט אחד', 'כל שורה היא הזמנה אחת.', 3) + CT('עמודה = מאפיין', 'כל עמודה היא פרט אחד שזוכרים על כל הזמנה. העמודה הראשונה היא המזהה.', 5) + '</div>') +
   BAND('note', 'שמות הטבלאות והעמודות נכתבים בדרך כלל באנגלית, כי כך כלי העבודה מצפים. את המשמעות שלהם מתעדים בעברית.', 6))

SS('e-sql', 'איך שואלים טבלה שאלה',
   ROW(DEF('שאילתה (Query)', 'שאלה שמנסחים למסד הנתונים בשפה שהוא מבין, והוא מחזיר שורות שעונות עליה.', '״אילו הזמנות של חמישי בערב חזרו למטבח?״', 1),
       DEF('שפת השאילתות SQL (Structured Query Language)', 'השפה המקובלת לשאילת שאלות ממסדי נתונים שבנויים מטבלאות. כמה מילות מפתח באנגלית, בסדר קבוע.', 'SELECT, FROM, WHERE: מה להציג, מאיזו טבלה, ואילו שורות.', 2)) +
   CHAT([('u', 'יש לי טבלה orders עם העמודות order_id, shift, waiter, returned. כתוב שאילתה שמציגה אילו הזמנות של חמישי בערב חזרו למטבח.'), ('a', 'הנה השאילתה. כדאי לבדוק שהערכים בעמודה shift אכן נכתבים כך אצלכם.')], 3) +
   BAND('dg', 'היום לא מקלידים את השאילתה. עוזר ה-AI כותב אותה. התפקיד שלנו: להבין מה כל חלק עושה, ולאשר שהתוצאה עונה על השאלה.', 5))

_ORD = ['order_id', 'shift', 'waiter', 'returned', 'minutes']
_ROWS = [['1201', 'thu_eve', 'יוסי', 'yes', '9'], ['1202', 'thu_eve', 'דנה', 'no', '4'], ['1203', 'fri_noon', 'יוסי', 'yes', '6'], ['1204', 'thu_eve', 'עומר', 'yes', '12'], ['1205', 'wed_eve', 'דנה', 'no', '5'], ['1206', 'thu_eve', 'יוסי', 'no', '7']]
QUERY('e-q1', 'שאילתה ראשונה', 'שאילתה ראשונה: אילו הזמנות של חמישי בערב חזרו?',
      'אילו הזמנות של חמישי בערב חזרו למטבח, ומי המלצר שלקח אותן?',
      [('SELECT order_id, waiter', '**מה להציג.** רק שתי עמודות: מספר ההזמנה והמלצר.'),
       ('FROM orders', '**מאיפה.** מהטבלה של ההזמנות.'),
       ("WHERE shift = 'thu_eve'", '**אילו שורות.** רק הזמנות של חמישי בערב. השאר יורדות.'),
       ("AND returned = 'yes'", '**תנאי נוסף.** מתוכן, רק אלה שחזרו למטבח.')],
      ('orders', _ORD, _ROWS, {1: {'cols': [0, 2]}, 3: {'rows': [0, 1, 3, 5]}, 4: {'rows': [0, 3]}}),
      'שתי הזמנות של חמישי בערב חזרו: 1201 של יוסי ו-1204 של עומר.',
      note='שימו לב לסדר הקריאה: מה מציגים, מאיפה, ואילו שורות נשארות. כל תנאי מוריד שורות.')

QUERY('e-q2', 'שאילתה שנייה', 'שאילתה שנייה: איפה ההמתנה הארוכה ביותר?',
      'בהזמנות של חמישי בערב, כמה דקות עברו מהשולחן למטבח, מהארוכה לקצרה?',
      [('SELECT order_id, minutes', '**מה להציג.** מספר ההזמנה ומספר הדקות.'),
       ('FROM orders', '**מאיפה.** מאותה טבלה.'),
       ("WHERE shift = 'thu_eve'", '**אילו שורות.** רק חמישי בערב.'),
       ('ORDER BY minutes DESC', '**באיזה סדר.** לפי דקות, מהגבוה לנמוך. השורות מסתדרות מחדש.')],
      ('orders', _ORD, _ROWS, {1: {'cols': [0, 4]}, 3: {'rows': [0, 1, 3, 5]}, 4: {'order': [3, 0, 5, 1, 2, 4]}}),
      'ההמתנה הארוכה ביותר בחמישי בערב הייתה 12 דקות, בהזמנה 1204. אחריה 9, 7 ו-4 דקות.',
      note='חלק חדש אחד בלבד: `ORDER BY`. כך לומדים שאילתות בקורס: בכל פעם חלק אחד, על שאלה עסקית אמיתית.')

MC1('e-q3', 'מה חסר בשאילתה?', 'מה לא בסדר בשאילתה שהעוזר כתב?',
    ['חסר תנאי על המשמרת, ולכן התוצאה כוללת הזמנות שחזרו בכל השבוע', 'אסור לבקש שתי עמודות באותה שאילתה', 'המילה FROM צריכה להופיע לפני SELECT', 'השאילתה תחזיר הודעת שגיאה ולא תרוץ'],
    'השאילתה תקינה ותרוץ בלי שגיאה. היא פשוט עונה על שאלה אחרת: אילו הזמנות חזרו בכלל. זו הסכנה העיקרית בעבודה עם עוזר AI: תשובה שנראית תקינה, על שאלה שלא שאלנו. לכן קוראים כל חלק.', art='🔎',
    story='אתי ביקשה מעוזר AI: ״אילו הזמנות של חמישי בערב חזרו למטבח?״. העוזר כתב: `SELECT order_id, waiter FROM orders WHERE returned = \'yes\'`. התוצאה כללה שלוש הזמנות: 1201, 1203 ו-1204.')

SS('e-real', 'בעולם האמיתי: מי כותב שאילתות היום',
   '<div class="big3">' + CT('🤖 הכתיבה', 'חלק גדול מהשאילתות נכתב היום בעזרת כלי AI, או בכלים שבונים אותן בגרירה. מעטים מקלידים אותן מאפס.', 1, 'neu') +
   CT('👓 הקריאה', 'מי שמאשר דוח צריך לדעת לקרוא שאילתה פשוטה: איזו טבלה, אילו שורות, איזה סדר. זו המיומנות שנבנה.', 2, 'good') +
   CT('🏗️ הפריסה', 'ד״ר עופרה אור תיקח את ההבנה הזאת לרמת פריסת הפרויקט בשטח. אצלנו: התשתית, ההיגיון, ומעט התנסות מעשית.', 3, 'good') + '</div>' +
   TOON('robot', 'אני כותב מהר. אתם מחליטים אם זו השאלה הנכונה.', 4))

HANDS('h-ent', 'הישויות בתהליך שלכם', 'עבודה עצמית: מה המערכת שלכם צריכה לזכור',
      'חזרו לסיפור המשתמש שכתבתם ולהחלטה שהגדרתם. נדרש: רשמו את הישויות שהמערכת שלכם צריכה לזכור, ולכל ישות מזהה ושניים או שלושה מאפיינים.',
      ['סמנו בסיפור המשתמש ובהחלטה את שמות העצם שחוזרים.', 'בחרו שלוש ישויות.', 'לכל ישות כתבו מזהה: מה מבדיל פריט אחד מאחר?', 'לכל ישות כתבו שניים או שלושה מאפיינים.', 'בדקו: האם הנתונים שההחלטה שלכם דורשת מופיעים ברשימה?'], 7,
      '<p><b>חשבונית:</b> מזהה: מספר חשבונית פנימי. מאפיינים: תאריך קבלה, סכום, תאריך חתימה.</p><p><b>ספק:</b> מזהה: מספר ספק. מאפיינים: שם, איש קשר.</p><p><b>מחלקה:</b> מזהה: קוד מחלקה. מאפיינים: שם, מנהל מאשר.</p><p><b>בדיקה:</b> ההחלטה דורשת זמן אישור לפי מחלקה. תאריך קבלה ותאריך חתימה מופיעים, והמחלקה היא ישות. אפשר לחשב.</p>',
      out='שלוש ישויות, לכל אחת מזהה ומאפיינים.')

SUMMARY('x-5', 'מה למדנו בחלק 5', [
    ('ישות', 'שם עצם שחוזר בדרישות, שיש ממנו הרבה: הזמנה, מנה, מלצר, שולחן.'),
    ('מאפיין ומזהה', 'מאפיין הוא פרט אחד על ישות. מזהה מבדיל בין פריטים. שם אינו מזהה.'),
    ('טבלה', 'טבלה לכל ישות, שורה לכל פריט, עמודה לכל מאפיין.'),
    ('שאילתה קוראים, לא מקלידים', 'מה להציג, מאיפה, אילו שורות, באיזה סדר. ובודקים שהיא עונה על השאלה שנשאלה.')])
HAVE('v-5', DELIV, 4)

# ------------------------------------------------------------------ part 6
opener(6, 'לעבוד עם עוזר AI כמו עם קבלן', 'איך מבקשים מהעוזר עבודה כך שהתוצאה תתאים למקרה שלנו, ואיך בודקים אותה?',
       ['משפרים הנחיה חלשה, חלק אחר חלק', 'בונים הנחיה בארבעה חלקים', 'מכירים שלוש מלכודות, כל אחת בשיחה מודגמת', 'עוברים על פלט של העוזר עם רשימת בדיקה', 'מתנסים בעוזר אמיתי, על התהליך שלכם'], 45)

SS('f-term', 'שני מושגים לפני שמתחילים',
   ROW(DEF('מודל שפה גדול (Large Language Model, LLM)', 'תוכנה שלמדה מכמות גדולה מאוד של טקסט, ויודעת להשלים טקסט באופן שנשמע סביר. עוזרי ה-AI בנויים על מודל כזה.', 'Claude, ChatGPT, Gemini.', 1),
       DEF('הנחיה (Prompt)', 'מה שכותבים לעוזר: הבקשה, עם כל מה שהוא צריך לדעת כדי לבצע אותה.', '״תבנה לי מערכת הזמנות למסעדה״ היא הנחיה. ראינו שהיא חלשה.', 2)) +
   BAND('dg', 'המודל מפיק טקסט שנשמע נכון. הוא אינו בודק אם הטקסט נכון. מכאן נגזר כל מה שנעשה בחלק הזה.', 3) +
   BAND('trap', 'העוזר יודע רק את מה שכתבתם לו. מה שנשאר בראש שלכם אינו חלק מההנחיה.', 4))

